import{_ as o,o as e,c as l,ag as d}from"./chunks/framework.BpFM782D.js";const h=JSON.parse('{"title":"Hookify Rules","description":"","frontmatter":{},"headers":[],"relativePath":"hookify/index.md","filePath":"hookify/index.md","lastUpdated":null}'),r={name:"hookify/index.md"};function a(i,t,s,n,c,u){return e(),l("div",null,[...t[0]||(t[0]=[d('<h1 id="hookify-rules" tabindex="-1">Hookify Rules <a class="header-anchor" href="#hookify-rules" aria-label="Permalink to &quot;Hookify Rules&quot;">​</a></h1><p>共 9 個 hookify rule。</p><table tabindex="0"><thead><tr><th>名稱</th><th>事件</th><th>動作</th><th>啟用</th><th>檔案</th></tr></thead><tbody><tr><td>block-dangerous-rm</td><td>bash</td><td>block</td><td>✅</td><td><code>hookify.block-dangerous-rm.local.md</code></td></tr><tr><td>block-eval-exec</td><td>file</td><td>block</td><td>✅</td><td><code>hookify.block-eval-exec.local.md</code></td></tr><tr><td>block-force-push</td><td>bash</td><td>block</td><td>✅</td><td><code>hookify.block-force-push.local.md</code></td></tr><tr><td>warn-git-add-all</td><td>bash</td><td>warn</td><td>✅</td><td><code>hookify.warn-git-add-all.local.md</code></td></tr><tr><td>warn-hardcoded-secret</td><td>file</td><td>warn</td><td>✅</td><td><code>hookify.warn-hardcoded-secret.local.md</code></td></tr><tr><td>warn-mutation</td><td>file</td><td>warn</td><td>✅</td><td><code>hookify.warn-mutation.local.md</code></td></tr><tr><td>warn-sensitive-files</td><td>file</td><td>warn</td><td>✅</td><td><code>hookify.warn-sensitive-files.local.md</code></td></tr><tr><td>warn-todo-fixme</td><td>file</td><td>warn</td><td>✅</td><td><code>hookify.warn-todo-fixme.local.md</code></td></tr><tr><td>warn-ts-any</td><td>file</td><td>warn</td><td>✅</td><td><code>hookify.warn-ts-any.local.md</code></td></tr></tbody></table><h2 id="block-dangerous-rm" tabindex="-1">block-dangerous-rm <a class="header-anchor" href="#block-dangerous-rm" aria-label="Permalink to &quot;block-dangerous-rm&quot;">​</a></h2><ul><li><strong>事件</strong>: <code>bash</code></li><li><strong>Pattern</strong>: <code>rm\\s+.*(-[a-zA-Z]*r[a-zA-Z]*f|-[a-zA-Z]*f[a-zA-Z]*r|--recursive\\s.*--force|--force\\s.*--recursive)</code></li><li><strong>動作</strong>: <code>block</code></li></ul><p><strong>rm -rf 已被攔截！</strong></p><p>這個命令可能造成不可逆的檔案刪除。請：</p><ul><li>確認目標路徑正確</li><li>考慮先用 <code>ls</code> 檢查目錄內容</li><li>改用更安全的方式（如 <code>trash</code> 或先備份）</li></ul><h2 id="block-eval-exec" tabindex="-1">block-eval-exec <a class="header-anchor" href="#block-eval-exec" aria-label="Permalink to &quot;block-eval-exec&quot;">​</a></h2><ul><li><strong>事件</strong>: <code>file</code></li><li><strong>Pattern</strong>: <code>\\beval\\s*\\(|new\\s+Function\\s*\\(|setTimeout\\s*\\(\\s*[&#39;&quot;</code>]|setInterval\\s*(\\s*[&#39;&quot;<code>]</code></li><li><strong>動作</strong>: <code>block</code></li></ul><p><strong>eval / new Function 已被攔截！</strong></p><p>動態執行程式碼是嚴重的安全風險（OWASP Top 10 - 注入攻擊）。</p><ul><li><code>eval()</code> 可被利用執行任意程式碼</li><li><code>new Function()</code> 同理</li></ul><p>請改用：</p><ul><li>JSON.parse() 解析資料</li><li>明確的條件邏輯取代動態執行</li><li>如確實需要，使用沙箱環境（如 vm2）</li></ul><h2 id="block-force-push" tabindex="-1">block-force-push <a class="header-anchor" href="#block-force-push" aria-label="Permalink to &quot;block-force-push&quot;">​</a></h2><ul><li><strong>事件</strong>: <code>bash</code></li><li><strong>Pattern</strong>: <code>git\\s+push\\s+.*--force(?!-with-lease)|git\\s+push\\s+.*\\s-f\\b</code></li><li><strong>動作</strong>: <code>block</code></li></ul><p><strong>git force push 已被攔截！</strong></p><p>Force push 會覆蓋遠端歷史，可能導致：</p><ul><li>團隊成員的工作遺失</li><li>CI/CD pipeline 混亂</li><li>無法復原的 commit 丟失</li></ul><p>請改用：</p><ul><li><code>git push --force-with-lease</code>（較安全，會檢查遠端是否有新 commit）</li><li>或重新 rebase 後正常 push</li></ul><h2 id="warn-git-add-all" tabindex="-1">warn-git-add-all <a class="header-anchor" href="#warn-git-add-all" aria-label="Permalink to &quot;warn-git-add-all&quot;">​</a></h2><ul><li><strong>事件</strong>: <code>bash</code></li><li><strong>Pattern</strong>: <code>git\\s+add\\s+(-A|\\.|\\*|--all)</code></li><li><strong>動作</strong>: <code>warn</code></li></ul><p><strong>偵測到 git add -A / git add . ！</strong></p><p>批量暫存可能意外包含：</p><ul><li><code>.env</code> 或機密檔案</li><li>大型二進位檔案</li><li>暫存的 debug 程式碼</li></ul><p>建議改用 <code>git add &amp;lt;specific-files&gt;</code> 逐一暫存。 先用 <code>git status</code> 確認要提交的檔案。</p><h2 id="warn-hardcoded-secret" tabindex="-1">warn-hardcoded-secret <a class="header-anchor" href="#warn-hardcoded-secret" aria-label="Permalink to &quot;warn-hardcoded-secret&quot;">​</a></h2><ul><li><strong>事件</strong>: <code>file</code></li><li><strong>Pattern</strong>: <code>(api[_-]?key|api[_-]?secret|password|token|secret[_-]?key|access[_-]?token|private[_-]?key|client[_-]?secret|auth[_-]?token|database[_-]?url)\\s*[:=]\\s*[&#39;&quot;</code>][a-zA-Z0-9_-/.+=]{8,}[&#39;&quot;<code>]</code></li><li><strong>動作</strong>: <code>warn</code></li></ul><p><strong>偵測到疑似硬編碼密鑰！</strong></p><p>程式碼中不應包含明文密鑰。請：</p><ul><li>改用環境變數：<code>process.env.API_KEY</code></li><li>或使用 secret manager（如 Vault、AWS Secrets Manager）</li><li>確認此值不會被 commit 到版本控制</li></ul><h2 id="warn-mutation" tabindex="-1">warn-mutation <a class="header-anchor" href="#warn-mutation" aria-label="Permalink to &quot;warn-mutation&quot;">​</a></h2><ul><li><strong>事件</strong>: <code>file</code></li><li><strong>Pattern</strong>: <code>(?&lt;!router)(?&lt;!history)(?&lt;!navigator)(?&lt;!stack)\\.(push|splice|pop|shift|unshift|reverse)\\s*\\(|Object\\.assign\\s*\\(\\s*[^{]|\\.sort\\s*\\(\\s*\\)</code></li><li><strong>動作</strong>: <code>warn</code></li></ul><p><strong>偵測到可能的陣列/物件 mutation！</strong></p><p>根據 coding-style 規範，必須使用 immutable 模式：</p><ul><li>Array: 用 <code>[...arr, item]</code> 取代 <code>.push()</code></li><li>Array: 用 <code>.filter()</code> 取代 <code>.splice()</code></li><li>Object: 用 <code>{ ...obj, key: val }</code> 取代 <code>Object.assign(target, ...)</code></li><li>Sort: 用 <code>.toSorted()</code> 取代 <code>.sort()</code>（ES2023+）</li></ul><p>Immutable 模式可避免隱藏副作用，更容易除錯和並行處理。</p><h2 id="warn-sensitive-files" tabindex="-1">warn-sensitive-files <a class="header-anchor" href="#warn-sensitive-files" aria-label="Permalink to &quot;warn-sensitive-files&quot;">​</a></h2><ul><li><strong>事件</strong>: <code>file</code></li><li><strong>Pattern</strong>: ``</li><li><strong>動作</strong>: <code>warn</code></li></ul><p><strong>正在編輯敏感檔案！</strong></p><p>請確認：</p><ul><li>沒有硬編碼任何密鑰或密碼</li><li>使用環境變數管理機密資訊</li><li>此檔案已加入 <code>.gitignore</code></li><li>不會意外 commit 到版本控制</li></ul><h2 id="warn-todo-fixme" tabindex="-1">warn-todo-fixme <a class="header-anchor" href="#warn-todo-fixme" aria-label="Permalink to &quot;warn-todo-fixme&quot;">​</a></h2><ul><li><strong>事件</strong>: <code>file</code></li><li><strong>Pattern</strong>: <code>\\b(TODO|FIXME|HACK|XXX)\\b</code></li><li><strong>動作</strong>: <code>warn</code></li></ul><p><strong>偵測到 TODO/FIXME/HACK 標記！</strong></p><p>這些標記代表技術債：</p><ul><li><strong>TODO</strong> — 待完成的功能</li><li><strong>FIXME</strong> — 已知問題需修復</li><li><strong>HACK</strong> — 臨時解法需重構</li></ul><p>請確認：</p><ul><li>是否有對應的 issue 追蹤</li><li>是否可以現在就處理</li><li>如果必須保留，請附上說明和負責人</li></ul><h2 id="warn-ts-any" tabindex="-1">warn-ts-any <a class="header-anchor" href="#warn-ts-any" aria-label="Permalink to &quot;warn-ts-any&quot;">​</a></h2><ul><li><strong>事件</strong>: <code>file</code></li><li><strong>Pattern</strong>: <code>:\\s*any\\b|as\\s+any\\b|&lt;any&gt;|,\\s*any\\s*&gt;|&lt;\\s*any\\s*,</code></li><li><strong>動作</strong>: <code>warn</code></li></ul><p><strong>偵測到 TypeScript <code>any</code> 類型！</strong></p><p>使用 <code>any</code> 會繞過類型檢查，降低類型安全。請考慮：</p><ul><li>使用具體類型或 interface</li><li>使用 <code>unknown</code> 替代 <code>any</code>（更安全，需要類型斷言）</li><li>如果是第三方庫缺少類型，考慮寫 <code>.d.ts</code> 宣告檔</li></ul>',56)])])}const p=o(r,[["render",a]]);export{h as __pageData,p as default};
